import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={page:'home',skin:'#bb825f',short:'#d4fc55',name:'JAY CARTER',style:'COUNTER PUNCHER',mode:'solo',spar:false,round:1,time:90,active:false,paused:false,power:72,speed:78,stamina:74,defense:69,playerHp:100,enemyHp:100,energy:100,enemyEnergy:100,damage:0,combo:0,cutSeconds:15,cutUsed:{},venue:0};
const venues=['THE FOUNDRY · NEW YORK','ROOFTOP · BROOKLYN','GOLDEN HALL · LONDON'];
const hex=h=>new THREE.Color(h);
function world(canvas,{home=false,solo=false}={}){
 const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.65));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;
 const scene=new THREE.Scene();scene.background=new THREE.Color(home?'#17201b':'#18201b');scene.fog=new THREE.Fog('#18201b',13,26);
 const camera=new THREE.PerspectiveCamera(33,1,.1,80);camera.position.set(0,4.4,11.8);camera.lookAt(0,1.15,0);
 scene.add(new THREE.HemisphereLight('#d8e4d6','#20231e',2.1));const key=new THREE.DirectionalLight('#fff0d6',3.3);key.position.set(-4,8,5);key.castShadow=true;key.shadow.mapSize.set(1024,1024);scene.add(key);const rim=new THREE.DirectionalLight('#91bfff',2.6);rim.position.set(3,5,-4);scene.add(rim);
 const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
 const floor=new THREE.Mesh(new THREE.CircleGeometry(15,48),mat('#252e28'));floor.rotation.x=-Math.PI/2;floor.position.y=-.12;floor.receiveShadow=true;scene.add(floor);
 // Four-sided ring, canvas-colored mat and rope rails
 const ring=new THREE.Group();scene.add(ring);const platform=new THREE.Mesh(new THREE.BoxGeometry(8.7,.3,7),mat('#d8d2bd'));platform.position.y=.12;platform.receiveShadow=true;ring.add(platform);
 const canvasMat=mat('#345b54');const canvasFloor=new THREE.Mesh(new THREE.BoxGeometry(8.35,.055,6.65),canvasMat);canvasFloor.position.y=.3;canvasFloor.receiveShadow=true;ring.add(canvasFloor);
 for(let x of [-3.88,3.88])for(let z of [-2.98,2.98]){const post=new THREE.Mesh(new THREE.BoxGeometry(.14,1.5,.14),mat(x<0?'#d4fc55':'#ed6354',.55,.18));post.position.set(x,.96,z);post.castShadow=true;ring.add(post)}
 for(let y of [.65,.98,1.31,1.64]){const ropeMat=mat(y===1.31?'#e7e4d8':'#e9eee2',.5);for(let z of [-2.98,2.98]){const r=new THREE.Mesh(new THREE.CylinderGeometry(.035,.035,7.75,8),ropeMat);r.rotation.z=Math.PI/2;r.position.set(0,y,z);ring.add(r)}for(let x of [-3.88,3.88]){const r=new THREE.Mesh(new THREE.CylinderGeometry(.035,.035,5.95,8),ropeMat);r.rotation.x=Math.PI/2;r.position.set(x,y,0);ring.add(r)}}
 // Atmospheric crowd and hanging lights
 for(let row=0;row<3;row++)for(let i=0;i<34;i++){const a=(i/34)*Math.PI*2;const r=8+row*.48;const color=['#8c8f76','#644d40','#344b51','#b1a184','#646c61'][i%5];const b=new THREE.Mesh(new THREE.SphereGeometry(.11+Math.random()*.07,7,6),mat(color));b.position.set(Math.cos(a)*r,.25+Math.random()*.22,Math.sin(a)*r);scene.add(b)}
 for(let x of [-3.8,0,3.8]){const lamp=new THREE.Mesh(new THREE.BoxGeometry(.68,.1,.22),mat('#fff0cb',.4));lamp.position.set(x,5.4,-3.9);scene.add(lamp);const spot=new THREE.SpotLight('#fff0dc',45,15,.56,.45,1.4);spot.position.set(x,5.3,-3);spot.target.position.set(x,0,0);scene.add(spot,spot.target)}
 function fighter({x=0,skin='#bb825f',trunks='#d4fc55',facing=1,shirt=false}={}){
   const g=new THREE.Group();g.position.set(x,.31,0);g.rotation.y=facing===1?Math.PI/2:-Math.PI/2;scene.add(g);
   const skinMat=mat(skin,.8),shortMat=mat(trunks,.7),dark=mat('#252624'),boot=mat('#1a1b19'),gloveMat=mat(facing===1?'#e8e4d7':'#e65345',.45),band=mat('#f2eee0');
   function mesh(geo,m,x,y,z,sx=1,sy=1,sz=1){const o=new THREE.Mesh(geo,m);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=true;o.receiveShadow=true;g.add(o);return o}
   mesh(new THREE.SphereGeometry(1,18,14),skinMat,0,1.32,0,.37,.52,.25); // torso
   mesh(new THREE.SphereGeometry(1,14,12),skinMat,0,1.76,.04,.22,.24,.22); // neck
   mesh(new THREE.SphereGeometry(1,20,16),skinMat,0,2.03,.04,.27,.34,.27); // head
   mesh(new THREE.SphereGeometry(.09,10,8),dark,0,2.07,.282,.7,.62,.35); // hair cap
   mesh(new THREE.BoxGeometry(.58,.42,.48),shortMat,0,.79,0);mesh(new THREE.BoxGeometry(.6,.11,.5),band,0,.94,0);
   const legs=[];for(let side of [-1,1]){const thigh=mesh(new THREE.CapsuleGeometry(.12,.48,5,9),skinMat,side*.17,.42,0,.9,1,.9);const shin=mesh(new THREE.CapsuleGeometry(.09,.38,4,8),skinMat,side*.17,.17,.08);mesh(new THREE.BoxGeometry(.19,.12,.32),boot,side*.17,.08,.19);legs.push({thigh,shin,side})}
   const arms=[];for(let side of [-1,1]){const upper=mesh(new THREE.CapsuleGeometry(.105,.32,4,8),skinMat,side*.34,1.26,.1);const fore=mesh(new THREE.CapsuleGeometry(.1,.27,4,8),skinMat,side*.35,1.28,.25);const glove=mesh(new THREE.SphereGeometry(.17,14,12),gloveMat,side*.36,1.33,.49,1,1,.88);mesh(new THREE.CylinderGeometry(.105,.105,.1,12),band,side*.36,1.32,.37);arms.push({upper,fore,glove,side})}
   // subtle sponsor-free waistband badge
   mesh(new THREE.BoxGeometry(.21,.055,.025),mat('#f3eee0'),0,.92,.26);
   return {g,arms,legs,home,phase:Math.random()*5,attack:null,guard:false,hit:0,step:0};
 }
 const left=fighter({x:-1.55,skin:'#bb825f',trunks:'#d4fc55',facing:1});const right=fighter({x:1.55,skin:'#8e593e',trunks:'#d94c42',facing:-1});
 function updateFighter(f,dt,player){f.phase+=dt;f.hit=Math.max(0,f.hit-dt);let extend=0,kind='jab',armSide=1;if(f.attack){f.attack.t+=dt;const t=f.attack.t,d=f.attack.dur;extend=t<d*.45?Math.sin(Math.PI*(t/(d*.9))):Math.max(0,Math.sin(Math.PI*((t-d*.45)/(d*.55))));if(t>=d)f.attack=null;else{kind=f.attack.kind;armSide=f.attack.arm}}const guard=f.guard?1:0;const sway=Math.sin(f.phase*2.7)*.035+f.step;
  f.g.position.x+=(f.targetX===undefined?f.g.position.x:f.targetX-f.g.position.x)*Math.min(1,dt*5);
  for(const a of f.arms){const active=a.side===armSide;const punch=active?extend:0;let elbowY=1.24,elbowZ=.22,gloveY=1.5,gloveZ=.5;
    if(guard){gloveY=1.7;gloveZ=.25;elbowY=1.35;elbowZ=.12}
    if(kind==='hook'){gloveY=1.48;gloveZ=.48;}
    if(kind==='upper'){gloveY=1.83;gloveZ=.42;}
    gloveY+=(1.47-gloveY)*punch;gloveZ+=(kind==='jab'?1.16:.91-gloveZ)*punch;elbowZ+=(.42-elbowZ)*punch;gloveY+=sway+(f.hit?-.12:0);
    function pose(mesh,x,y,z,scale){mesh.position.set(x,y,z);mesh.scale.set(scale,scale,scale);mesh.rotation.x=-.22-punch*.22;mesh.rotation.z=0}
    pose(a.upper,a.side*.31,1.39+ (elbowY-1.39)*.3,.09+elbowZ*.25,.105);pose(a.fore,a.side*.34,(elbowY+gloveY)/2,(elbowZ+gloveZ)/2,.095);pose(a.glove,a.side*.36,gloveY,gloveZ,.17);
  }
  for(const leg of f.legs){const stride=Math.sin(f.phase*5+(leg.side>0?Math.PI:0))*(f.step?0.12:0.018);leg.thigh.position.z=stride;leg.shin.position.z=stride*.5;}
  f.g.position.y=.31+Math.sin(f.phase*4)*.018+(f.hit?-.08:0);
 }
 function resize(){const w=canvas.clientWidth||innerWidth,h=canvas.clientHeight||innerHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix()}
 const ro=new ResizeObserver(resize);ro.observe(canvas);resize();return {renderer,scene,camera,left,right,fighter,updateFighter,resize};
}
