const worlds={};worlds.home=world($('#preview'),{home:true});worlds.fight=world($('#scene'));worlds.custom=world($('#customScene'),{solo:true});worlds.gym=world($('#gymScene'));worlds.versus=world($('#versusScene'));
function page(name){state.page=name;$$('.page').forEach(p=>p.classList.remove('show'));$('#page-'+name).classList.add('show');$$('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===name));requestAnimationFrame(()=>Object.values(worlds).forEach(w=>w.resize()))}
$$('.nav button').forEach(b=>b.onclick=()=>page(b.dataset.page));
function applyFighter(){const name=$('#boxerName').value.trim().toUpperCase()||'JAY CARTER';state.name=name.slice(0,18);state.style=$('#styleSelect').value.toUpperCase();const c=worlds.custom.left; c.g.traverse(o=>{if(o.isMesh&&o.material?.color){if(o.material.color.getHexString()==='bb825f')o.material.color.set(state.skin);if(o.material.color.getHexString()==='d4fc55')o.material.color.set(state.short)}});$('#saveBoxer').textContent='Fighter saved ✓';setTimeout(()=>$('#saveBoxer').textContent='Save fighter',1600);toast('FIGHTER UPDATED · '+state.name)}
$('#saveBoxer').onclick=applyFighter;$('#boxerName').oninput=()=>{state.name=$('#boxerName').value.toUpperCase()||'JAY CARTER'};$('#styleSelect').onchange=e=>state.style=e.target.value.toUpperCase();$('#skinSwatches').onclick=e=>{const b=e.target.closest('[data-skin]');if(!b)return;state.skin=b.dataset.skin;$$('#skinSwatches .swatch').forEach(s=>s.classList.toggle('selected',s===b));applyFighter()};$('#shortSwatches').onclick=e=>{const b=e.target.closest('[data-color]');if(!b)return;state.short=b.dataset.color;$$('#shortSwatches .swatch').forEach(s=>s.classList.toggle('selected',s===b));applyFighter()};
$('#heightSlider').oninput=e=>$('#heightLabel').textContent=(5+Math.floor(+e.target.value/33))+'′ '+(10+Math.round(+e.target.value%33/3.3))+'″';$('#reachSlider').oninput=e=>$('#reachLabel').textContent=(66+Math.round(+e.target.value/100*12))+' in';
let toastTimer;function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}
